using System.Diagnostics;
using System.Drawing;
using System.Text.RegularExpressions;
namespace RF4FriendLauncher;
public sealed class MainForm:Form
{
 readonly LauncherConfig cfg;readonly AccountService account=new();readonly HostsService hosts=new();
 readonly TextBox ip=new(),user=new(),pass=new(),game=new();readonly ComboBox region=new();readonly CheckBox auto=new();readonly Label uid=new(),status=new(),serverDot=new();
 public MainForm(){cfg=ConfigService.Load();Text="RF4 Friend Launcher";StartPosition=FormStartPosition.CenterScreen;MinimumSize=new Size(760,680);Size=new Size(820,730);Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(15,18,24);ForeColor=Color.FromArgb(232,236,242);Build();LoadCfg();Shown+=async(_,_)=>{if(auto.Checked&&!string.IsNullOrWhiteSpace(user.Text)&&pass.Text!="")await Auth(false,false);};}
 void Build()
 {
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(26),ColumnCount=1,RowCount=5,BackColor=BackColor};
  root.RowStyles.Add(new RowStyle(SizeType.Absolute,76));root.RowStyles.Add(new RowStyle(SizeType.Absolute,215));root.RowStyles.Add(new RowStyle(SizeType.Absolute,170));root.RowStyles.Add(new RowStyle(SizeType.Absolute,82));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(root);
  var head=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};head.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));head.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,180));
  head.Controls.Add(new Label{Text="RF4 FRIEND LAUNCHER",Font=new Font("Segoe UI Semibold",20),Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,ForeColor=Color.White},0,0);
  var online=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,WrapContents=false,Padding=new Padding(0,20,0,0)};serverDot=new Label{Text="●",AutoSize=true,Font=new Font("Segoe UI",12),ForeColor=Color.Gray};online.Controls.Add(new Label{Text="  сервер",AutoSize=true,ForeColor=Color.FromArgb(150,158,170),Padding=new Padding(0,3,0,0)});online.Controls.Add(serverDot);head.Controls.Add(online,1,0);root.Controls.Add(head,0,0);
  root.Controls.Add(AccountPanel(),0,1);root.Controls.Add(GamePanel(),0,2);root.Controls.Add(ActionPanel(),0,3);
  var foot=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2};foot.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,145));foot.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));foot.RowStyles.Add(new RowStyle(SizeType.Absolute,30));foot.RowStyles.Add(new RowStyle(SizeType.Percent,100));uid.Text=cfg.AccountUid>0?"UID  "+cfg.AccountUid:"UID  —";uid.Dock=DockStyle.Fill;uid.Font=new Font("Segoe UI Semibold",9);status.Text="Готов к работе";status.Dock=DockStyle.Fill;status.ForeColor=Color.FromArgb(145,155,170);foot.Controls.Add(uid,0,0);foot.Controls.Add(status,1,0);var hint=new Label{Text="Учетная запись и UID привязаны к серверу. Пароль хранится локально в зашифрованном виде.",Dock=DockStyle.Fill,ForeColor=Color.FromArgb(100,110,125),Font=new Font("Segoe UI",8.5f)};foot.Controls.Add(hint,0,1);foot.SetColumnSpan(hint,2);root.Controls.Add(foot,0,4);
 }
 Control AccountPanel(){var g=Panel("АККАУНТ");var t=T(4,4);t.ColumnStyles[0]=new ColumnStyle(SizeType.Absolute,75);t.ColumnStyles[2]=new ColumnStyle(SizeType.Absolute,75);AddText(t,"Логин",user,0,0);AddText(t,"Пароль",pass,2,0);pass.UseSystemPasswordChar=true;var reg=B("Регистрация");reg.Click+=async(_,_)=>await Auth(true,true);var login=B("Войти",true);login.Click+=async(_,_)=>await Auth(false,true);t.Controls.Add(reg,1,1);t.Controls.Add(login,3,1);auto.Text=" Автоматический вход";auto.ForeColor=ForeColor;auto.BackColor=Color.Transparent;auto.Dock=DockStyle.Fill;t.Controls.Add(auto,1,2);t.SetColumnSpan(auto,3);var n=L("Сессия");n.Text="Токен и учетные данные сохраняются только на этом ПК.";n.Font=new Font("Segoe UI",8.5f);n.ForeColor=Color.FromArgb(105,115,130);t.Controls.Add(n,1,3);t.SetColumnSpan(n,3);g.Controls.Add(t);return g;}
 Control GamePanel(){var g=Panel("ИГРА И СЕРВЕР");var t=T(4,3);t.ColumnStyles[0]=new ColumnStyle(SizeType.Absolute,105);t.ColumnStyles[2]=new ColumnStyle(SizeType.Absolute,105);t.ColumnStyles[3]=new ColumnStyle(SizeType.Absolute,105);AddText(t,"IP сервера",ip,0,0);var my=B("Мой сервер");my.Click+=(_,_)=>SetServer();var off=B("Официальная");off.Click+=(_,_)=>SetOfficial();t.Controls.Add(my,2,0);t.Controls.Add(off,3,0);AddText(t,"rf4_x64.exe",game,0,1);t.SetColumnSpan(game,2);var br=B("Обзор");br.Click+=(_,_)=>Browse();t.Controls.Add(br,3,1);t.Controls.Add(L("Регион"),0,2);region.Items.AddRange(new object[]{"CN","RU","EU","US"});region.DropDownStyle=ComboBoxStyle.DropDownList;region.BackColor=Color.FromArgb(31,36,46);region.ForeColor=ForeColor;t.Controls.Add(region,1,2);t.SetColumnSpan(region,2);g.Controls.Add(t);return g;}
 Control ActionPanel(){var t=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new Padding(0,8,0,0)};t.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,72));t.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,28));var b=B("▶  ЗАПУСТИТЬ ИГРУ",true);b.Font=new Font("Segoe UI Semibold",12);b.Height=52;b.BackColor=Color.FromArgb(38,160,104);b.ForeColor=Color.White;b.Click+=(_,_)=>Launch();t.Controls.Add(b,0,0);t.Controls.Add(new Label{Text="UID назначает сервер",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.FromArgb(105,115,130)},1,0);return t;}
 Control Panel(string title){return new GroupBox{Text=title,Dock=DockStyle.Fill,Padding=new Padding(14),ForeColor=Color.FromArgb(180,188,200),BackColor=Color.FromArgb(21,25,33),Font=new Font("Segoe UI Semibold",9)};}
 static TableLayoutPanel T(int c,int r){var t=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=c,RowCount=r};for(int i=0;i<r;i++)t.RowStyles.Add(new RowStyle(SizeType.Percent,100f/r));for(int i=0;i<c;i++)t.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/c));return t;}
 void AddText(TableLayoutPanel t,string label,TextBox box,int c,int r){t.Controls.Add(L(label),c,r);box.Dock=DockStyle.Fill;box.BackColor=Color.FromArgb(31,36,46);box.ForeColor=Color.FromArgb(235,238,244);box.BorderStyle=BorderStyle.FixedSingle;box.Margin=new Padding(4);t.Controls.Add(box,c+1,r);}
 Label L(string s)=>new(){Text=s,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,ForeColor=Color.FromArgb(185,192,202)};
 Button B(string s,bool accent=false){var b=new Button{Text=s,Dock=DockStyle.Fill,Margin=new Padding(4),FlatStyle=FlatStyle.Flat,BackColor=accent?Color.FromArgb(45,55,72):Color.FromArgb(31,36,46),ForeColor=Color.FromArgb(232,236,242),FlatAppearance={BorderColor=Color.FromArgb(58,66,80)}};return b;}
 void LoadCfg(){ip.Text=cfg.ServerIp;game.Text=cfg.GamePath;region.Text=string.IsNullOrWhiteSpace(cfg.GameRegion)?"CN":cfg.GameRegion;user.Text=cfg.AccountUsername;pass.Text=PasswordProtection.Unprotect(cfg.AccountPasswordProtected);auto.Checked=cfg.AutoLogin;try{if(hosts.Active()){status.Text="Подключение через ваш сервер";serverDot.ForeColor=Color.FromArgb(70,200,130);}else serverDot.ForeColor=Color.FromArgb(120,125,135);}catch{}}
 void Save(){cfg.ServerIp=ip.Text.Trim();cfg.GamePath=game.Text.Trim();cfg.GameRegion=region.Text.Trim();cfg.AccountUsername=user.Text.Trim();cfg.AccountPasswordProtected=PasswordProtection.Protect(pass.Text);cfg.AutoLogin=auto.Checked;ConfigService.Save(cfg);}
 async Task Auth(bool register,bool show){try{if(string.IsNullOrWhiteSpace(user.Text)||string.IsNullOrEmpty(pass.Text))throw new InvalidOperationException("Введи имя аккаунта и пароль.");SetServer();var old=cfg.AccountUid;var r=register?await account.RegisterAsync(user.Text.Trim(),pass.Text):await account.LoginAsync(user.Text.Trim(),pass.Text);SessionService.Save(user.Text.Trim(),r.LoginToken,r.TokenTimestamp);cfg.AccountUid=r.Uid;Save();uid.Text="UID  "+r.Uid;status.Text=$"Аккаунт «{user.Text.Trim()}» авторизован · UID {r.Uid}";serverDot.ForeColor=Color.FromArgb(70,200,130);if(old>0&&old!=r.Uid)MessageBox.Show($"Сервер вернул другой UID ({r.Uid}). Старый UID ({old}) не используется.","Проверка UID",MessageBoxButtons.OK,MessageBoxIcon.Warning);}catch(Exception e){status.Text=register?"Регистрация не выполнена":"Вход не выполнен";serverDot.ForeColor=Color.FromArgb(220,100,100);if(show)MessageBox.Show(e.Message,register?"Регистрация не выполнена":"Вход не выполнен",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 void SetServer(){try{hosts.SetServer(ip.Text);Save();status.Text="Подключение через ваш сервер";serverDot.ForeColor=Color.FromArgb(70,200,130);}catch(Exception e){serverDot.ForeColor=Color.FromArgb(220,100,100);MessageBox.Show(e.Message,"Не удалось переключить hosts",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 void SetOfficial(){try{hosts.SetOfficial();Save();status.Text="Официальный режим";serverDot.ForeColor=Color.FromArgb(120,125,135);}catch(Exception e){MessageBox.Show(e.Message,"Не удалось вернуть официальный режим",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 void Browse(){using var d=new OpenFileDialog{Filter="RF4 executable (rf4_x64.exe)|rf4_x64.exe|Executable (*.exe)|*.exe",Title="Выбери rf4_x64.exe",CheckFileExists=true};if(d.ShowDialog(this)==DialogResult.OK){game.Text=d.FileName;Save();}}
 void Launch(){try{var p=game.Text.Trim().Trim('"');if(!File.Exists(p)||!string.Equals(Path.GetFileName(p),"rf4_x64.exe",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Выбери существующий файл rf4_x64.exe.");var r=string.IsNullOrWhiteSpace(region.Text)?"CN":region.Text.Trim();if(!Regex.IsMatch(r,"^[A-Za-z0-9_-]+$"))throw new InvalidOperationException("Регион может содержать только латинские буквы, цифры, _ и -.");Save();Process.Start(new ProcessStartInfo{FileName=p,WorkingDirectory=Path.GetDirectoryName(p)!,UseShellExecute=true,Arguments="-region "+r});status.Text="Игра запущена";}catch(Exception e){MessageBox.Show(e.Message,"Не удалось запустить игру",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
}